P=Path('entregables/ronda_8_9_20261031');a=json.loads((P/'mensajes_normalizados.json').read_text());mf=json.loads((P/'media_manifest.json').read_text()) if (P/'media_manifest.json').exists() else [];refs=json.loads((P/'referencias_locales.json').read_text());reels=json.loads((P/'reels_descarga.json').read_text());tr=json.loads((P/'transcripciones_media.json').read_text()) if (P/'transcripciones_media.json').exists() else {}
notes={
'Jesus_Puertas':('Jesús Puertas: encargo nuevo','Los tres audios nuevos cambian el encargo: NO quiere salir él ni usar su voz. Quitar cocina por metro y “Carpintería Jesús”. Pide “Paulina Puertas y Cocinas” (confirmar redacción exacta), MDF desde $2,500 y caobilla desde $3,500; solo esos precios. Quiere trabajadores realistas como los reels de herrería. No pedirle otra vez su foto para hacer avatar. Audios transcritos con Whisper medium; conservar revisión humana para la ortografía del material.','proceso|instagram|precio|voz|carpinter|herrero|realista'),
'Ignacio':('Ignacio Iglesia: Colorado y referencia','No confundir con Ignacio Corona (generadores). En texto confirma Chevrolet Colorado 2019, 6 cilindros, americana/afiliada, cámara de reversa, $225 mil a tratar. Se descargan sus 17 fotos del 20 oct UTC. Referencia de CARROS: Dctql18iSBC, enviada por Carlos el 23 oct con promesa de voz encima. Dc9DMF7pVkl es un reel religioso del mismo chat; revisado visualmente y NO sirve de referencia de la camioneta.','Colorado|225|Dctql|haré un vídeo'),
'BYD_Rafael':('BYD: nombre, tarjeta, referencias y material','Nombre en texto: Rafael Hernández. La tarjeta revisada amplía: Rafael Hernández Ortiz, asesor de ventas BYD AZCAPOTZALCO; WhatsApp 55 7386 9438. Tarjeta muestra SONG PLUS, KING y DOLPHIN; no implica que sean la oferta elegida. Hay fotos de autos, agencia, tarjeta y selfies más videos. Carlos mandó cuatro reels: DO4g4PkEcis (asesor fuera/dentro de auto), DdFSF4mM0p6 (asesora mostrando auto e interior), DWt3b6Ejdla (recorrido de lote con voz), DYA5q1dgLty (asesor caminando en agencia). Reels descargados y vistos en hoja de contacto. Falta elegir modelo/oferta y condiciones, no inventar bonos o mensualidades. En audio dice que enviará fichas técnicas y pregunta por crear página de Facebook; Carlos debe verificar si ya existe. El ejemplo hablado de autonomía/carga no es una ficha autorizada del modelo.','instagram|Rafael|guión|plan|nombre'),
'Fernando':('Fernando: guion corregido y audio recibido','Sí mandó el audio: 31 oct 04:02:44 UTC, seguido por “Aquí tienes el audio”. NO volver a pedirlo. Guion completo preservado en Fernando_guion_original.txt. Usar accesorios reales: impresora chica, lector tipo pistola y caja de software. El cliente cambió el guion el 30 oct 19:26 UTC: paquete $3,500, pago al funcionar, visita en CDMX/área metropolitana, instalación, capacitación y soporte en llamada un año sin costo. El guion nuevo no menciona IVA: confirmar antes de añadirlo. Whisper del audio confirma paquete $3,500 e incluye soporte/asesoría en llamada o videollamada por un año. El cierre tiene dos tomas consecutivas: primera “por un WhatsApp” y segunda correcta “por WhatsApp”; conservar la segunda, sin duplicar CTA.','REALICÉ UNAS MEJORAS|Aquí tienes el audio|accesorios|Punto de venta en la nube'),
'Lisbeth':('Lisbeth: plano, precios y WhatsApp nuevo','No se localizaron plano, croquis ni tabla de medidas/precios. SÍ se encontró el número nuevo: 3221072021, chat 252291428913257@lid. La clienta lo confirmó el 30 oct 20:42 UTC y después confirmó WhatsApp Business. En ese chat envió la referencia de la presa: https://www.facebook.com/share/r/1G7syMJFvB/. Se revisaron las 15 imágenes locales de WhatsApp: son terreno/accesos, selfie y captura de instalación de WhatsApp; la última imagen NO es un plano. No dibujar un plano inventado. El cliente dijo “Sí tendrán agua y luz”: confirmar si es disponibilidad futura o infraestructura ya instalada. Plano y precios siguen sin respuesta en ambos chats; no volver a pedir el número nuevo.','número de WhatsApp no es|plano|precio por lote|WhatsApp nuevo|Si tendrán agua|3221072021|1G7syMJFvB'),
'Victor':('Víctor: v7 y correcciones','Video local: clientes/Victor/video/Servilin_obra_fina_v7.mp4. Se preserva copia de los dos videos enviados por Carlos al chat de Víctor el 31 oct 04:57 UTC; sin asumir por texto cuál es v7 hasta comparar. Evaluación propia de v7 en ronda1a: 7 actual → 8 proyectada. Corregir arranque con trabajador y resultado real, evitar repetición/superposiciones y revisar marca en voz. Glimmer dice “Cervilín”: no tratar una diferencia ortográfica del transcriptor como prueba de error fonético; revisar audio antes de regenerar. Preparar limpieza industrial separado, no anuncio de empleo.','versión 7|clips reales|independiente|Que se vea'),
'Guillermo':('Guillermo: audio y base correcta Modal','La indicación de Carlos es usar el video generado en Modal que ya mandó antes, no asumir far12. Están localizadas las dos bases techo v6 con música: caen/suben, copiadas en media/Guillermo/. El cliente contestó “Perfecto mi buen / Así era” después de DOS videos seguidos: no distingue la variante. Audios recientes y referencias del chat guardados. Audio del cliente 30 oct 02:05 UTC: pide que las láminas CAIGAN ARRIBA para que por debajo se aprecie la estructura. Esto respalda la base salida_v6_caen/Guillermo_techo_proceso_musica.mp4. La aprobación escrita posterior está después de ambas variantes; revisar correspondencia del envío si se requiere certeza de cuál mandó a su comprador. El anuncio Guillermo_Pixar_v5_metodo es de la agencia Nexus, no de Vicens.','instagram|Perfecto mi buen|Así era|clips cortos|como se hizo'),
'BDPro':('BD Pro: otro servicio','Los textos separan dos campañas: pistas/vinil por un lado y AUDIO/PANTALLAS por otro. Carlos: “Yo creo que dejar lo de vinil en un vídeo y audio pantallas para otro video”; cliente: “De acuerdo. Sí”. No elegir arbitrariamente cuál de audio o pantallas será el segundo anuncio. Pistas tienen tabulador por tipo/medida, sin precio único confirmado. Cliente informó cero mensajes el 30 oct; Carlos debe revisar campaña y destino de WhatsApp.','audio pantallas|otro servicio|propio vide|No he recibido|tabulador'),
'Israel':('Israel: referencias y audio','Marca corregida por cliente: SIRLed. Tres reels enviados por Carlos el 27 oct: Dbjy5rnujqg, DZW99XNtlqQ y DduYDrtJQJa. Están copiados desde referencias locales con sus enlaces exactos. Pidió guion para leer y preguntó cómo mandar voz; no se encontró audio nuevo del guion en este corte. No confundir Israel_1..4 de ideas_aprobar con anuncio final.','instagram|nombre es SIRLed|envío la voz|guión para leer'),
'Mariano':('Mariano: gancho Spider-Man y casas','Referencia final localizada DfEChbGT2px, Carlos la mandó el 29 oct 17:15 UTC. También DXeU5dDkeXe; cliente pidió “Mejor en este puras casas”. Están las copias locales de gancho y referencia. La última muestra es Vizcaino_v5_gancho_spiderman_v2.mp4. Aún hay que confirmar precio/modelo y que los lugares correspondan al desarrollo real.','instagram|puras casas|gancho|dron'),
'Veronica':('Verónica: gancho hablado, entrada de dron y decoración','Chat correcto 57844753760482@lid (789 101 5551). Se verificó porque el otro número 833 458 0087 es Mr. Patio, NO Verónica; se corrigió la identificación antes de entregar. Torre El Charro, Tampico, desde $7,600,000 MXN. Referencia local DfGOIz3z7uZ.mp4 copiada. No se localizó en mensajes de texto un enlace exacto a ese código; mantenerlo como referencia local con asociación de mensaje por confirmar. Audios revisados con Whisper medium: reclama que la fachada tomada de la publicación está rayada, corrige dólares a PESOS y pide voz menos robotizada. Usar fachada limpia y real; los audios seleccionados no contienen por sí solos instrucciones de dron/decoración, que constan como tarea del plan.','Exclusiva torre|dólar|robot|instagram|gancho'),
'Tatuador':('Adrián: hard cut y cara real','Cliente rechaza verse hecho con IA. Textos: “Prefiero algo más como esto”, “No se puede hacer uno como este?” y “Igual puedo hacerte tomas que me pidas”. Envío 30 oct 19:57 UTC: dos videos de referencia; posteriores documentos contienen material en calidad original, incluidos Adrian 3.mov e IMG_9331.MOV. Preservar todos para identificar frontal real. No concluir que falta cara sin revisar esos documentos. Referencias locales CqLdHoAp585 / DU2DBv9EX6J; hard cut 18.9 s con cortes secos, oscuro/neón/flash según el análisis previo, no avatar nuevo.','no me convence|Prefiero algo|No se puede|mercado|tomas q|El minimo'),
'Rachel':('Rachel: referencias y aprobación de cuadros','Clou SPA, Calzada Cuauhtémoc 876 Prohogar, Mexicali. Cuatro reels de referencia copiados: Ddg6Crlg4jJ, DPtNklUjfxr, DE2wMoPSpd9, DXR4VxJRPfj. Identificar quién los mandó en citas originales. Cliente dijo que no pudo abrir uno de Instagram; no asumir que aprobó la referencia por habérsela enviado. No inventar certificación/apartado. Cuadros a Carlos antes de animar.','instagram|dirección es|Calzada|no pude|No pude|Gracias'),
'Blanca':('Blanca: referencia y problema de identidad','Hablar Hablando, Blanca Cruz Solís. Reportó desfase de labios, voz lenta y cara que no se parece; prefiere grabarse ella. Confirmó valoración $1,800, terapia $850 una vez por semana. Enlaces de chat: perfil yohablo.tuhablas, reels DV9o6DwjUZE y DWUG_L0EUCz. Los seis reels adicionales locales se marcan como ideas guardadas; no atribuir su envío a Blanca sin mensaje exacto. No repetir producción con avatar rechazado.','instagram|ultra falso|no me parezco|mejor lo grabo|desfasado|valoración'),
'JesusRarAmore':('Jesús Rar~Amore: cápsulas','Referencia DcdiHfmTjbf localizada y copiada. En el chat aparecen además DcBPbR0IkIA y DcMibTMyHU3. El pedido de que una persona enferma se alivie al entrar las cápsulas es una promesa de curación inmediata: no se traslada al guion. Pedir producto/ingredientes/oferta reales y mostrar uso sin prometer resultados.','instagram|cápsulas|Enferma')}
lines=['# Datos del encargo · A5','','Corte de consulta: 31 oct 2026. Fechas de este informe en UTC; Nogales = UTC−7. Lectura de WhatsApp, descargas y copias locales únicamente; ningún envío. Mensajes completos y metadatos en chats/*.json. La fuente de una transcripción automática es el audio original, no texto escrito del cliente.','']
for n,(title,note,pattern) in notes.items():
 lines+=['## '+title,'',note,'','### Mensajes originales','']
 matches=[x for x in a if x['chat']==n and x['type']=='chat' and re.search(pattern,x['body'],re.I)]
 for x in matches[-8:]:
  author='Carlos' if x['fromMe'] else 'Cliente';date=datetime.datetime.fromtimestamp(x['t'],datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S')
  lines.append(f'**{author} · {date} · `{x["id"]}`**\n\n> '+x['body'].replace('\n','\n> ')+'\n')
 trans=[x for x in mf if x['chat']==n and x['id'] in tr]
 if trans:
  lines+=['### Audios: transcripción automática Whisper medium','']
